"""Evaluate rule-language expressions using the generated standalone parser."""
from calc._parser import Lark_StandAlone, Transformer


class Eval(Transformer):
    def num(self, t):
        return float(t[0])
    def true(self, _):
        return 1.0
    def false(self, _):
        return 0.0
    def add(self, t):
        return t[0] + t[1]
    def sub(self, t):
        return t[0] - t[1]
    def mul(self, t):
        return t[0] * t[1]
    def div(self, t):
        return t[0] / t[1]


_parser = Lark_StandAlone()


def evaluate(text):
    return Eval().transform(_parser.parse(text))

import unittest
from calc.evaluate import evaluate

class T(unittest.TestCase):
    def test_true_literal(self):
        self.assertEqual(evaluate("true + 1"), 2.0)
    def test_false_literal(self):
        self.assertEqual(evaluate("false * 3"), 0.0)

